const I=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(n,d=2)=>n==null?'—':n.toLocaleString('ru-RU',{minimumFractionDigits:d,maximumFractionDigits:d}),uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const mapNames={wholesale:'Оптовая торговля',retail:'Розничная торговля',hotel:'Гостиницы',food:'Общественное питание',realty:'Операции с недвижимостью',services:'Другие рыночные услуги',market:'Сборы за торговые места',internet:'Оборот через Интернет',stock:'Товары для продажи населению'},freqNames={month:'Месячная',quarter:'Квартальная',year:'Годовая'};
function newCompany(name='Моя организация'){return{id:uid(),name,okpo:'',inn:'',territory:'',address:'',activity:'',gked:'',director:'',phone:'',email:'',mappingConfirmed:false,rules:E.defaultRules(),mappingRevision:2,drafts:{}};}
function initial(){const c=newCompany();return{version:1,companies:[c],active:c.id,sources:[],year:2026,trash:[]};}
let state;try{state=JSON.parse(localStorage.getItem(STORE))||initial();if(state.version!==1||!state.companies?.length)state=initial();}catch{state=initial();}
let page=location.hash.slice(1)||'overview',frequency='all',part=state.part||Number(state.sources.filter(s=>s.companyId===state.active).at(-1)?.end?.slice(5,7))||1,sourceId='',ms=null,timer,busy=false,storageError=false;
const C=()=>state.companies.find(c=>c.id===state.active)||state.companies[0],sources=()=>state.sources.filter(s=>s.companyId===C().id),accounts=()=>Object.assign({},...sources().map(s=>s.accounts));
function save(){state.part=part;try{localStorage.setItem(STORE,JSON.stringify(state));storageError=false;}catch{storageError=true;toast('Сохранение в браузере недоступно. Скачайте резервную копию.',true);}}
function invalidate(){for(const c of state.companies)for(const d of Object.values(c.drafts))d.reviewed=false;}
