function toolbar(){const years=[...new Set([2024,2025,2026,2027,2028,...state.sources.map(s=>+s.end.slice(0,4))])].filter(y=>y>2000).sort();return`<div class="toolbar"><div class="org-select"><span class="org-icon">${I('building')}</span><select id="org-select" aria-label="Организация">${state.companies.map(c=>`<option value="${c.id}" ${c.id===C().id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="icon-button" data-action="company" aria-label="Реквизиты организации">${I('edit')}</button></div><label class="year-select">${I('calendar')}<select id="year-select" aria-label="Отчётный год">${years.map(y=>`<option ${state.year===y?'selected':''}>${y}</option>`).join('')}</select></label></div>`;}
function heading(title,description,actions=''){return`<div class="page-heading"><div><div class="eyebrow">ОТЧЁТНОСТЬ В НАЦСТАТКОМ КР</div><h1>${title}</h1><p>${description}</p></div><div class="actions heading-actions">${actions}</div></div>`;}
const uploadButton=()=>`<button class="btn primary" data-action="upload">${I('plus')}Загрузить ОСВ</button>`;
function issues(){return[...sources().flatMap(E.sourceChecks),...E.periodConflicts(sources()),...E.mappingChecks(C().rules,accounts()),...(!C().mappingConfirmed&&sources().length?[{level:'warning',text:'Подтвердите назначение счетов для видов деятельности',action:'mapping'}]:[]),...(!C().okpo?[{level:'warning',text:'Заполните ОКПО организации',action:'company'}]:[])];}
function monthCoverage(){return E.MONTH_NAMES.map((_,i)=>{const p=E.periodFor('month',state.year,i+1);return{ready:E.resolve(sources(),p.start,p.end).ok,covered:sources().some(s=>s.start<=p.end&&s.end>=p.start)};});}
function stats(){const months=monthCoverage().filter(m=>m.ready).length,iss=issues();return`<div class="stats-grid">${[['Ведомостей загружено',sources().length,sources().length?'Для выбранной организации':'Начните с импорта из 1С','file',''],['Форм отчётности',F.length,'Месяц, квартал и год','reports','blue'],['Месяцев для расчёта',months+'<span style="font-size:13px;color:#a3b4a7;font-weight:400"> / 12</span>','Полностью покрытые периоды','calendar',''],['Требуют внимания',iss.length,iss.length?'Проверьте перед выгрузкой':'Замечаний к данным нет','check',iss.length?'amber':'']].map(([label,value,caption,icon,color])=>`<div class="stat-card"><div><div class="stat-card-label">${label}</div><div class="stat-value">${value}</div><div class="stat-caption">${caption}</div></div><div class="stat-icon ${color}">${I(icon)}</div></div>`).join('')}</div>`;}
function intake(){const cov=monthCoverage();return`<div class="intake-grid"><section class="panel upload-panel"><div class="panel-head"><div><h2><span class="section-number">01</span>Загрузите ведомость из 1С</h2><p>Добавьте один файл или несколько периодов</p></div><span class="file-types">XLS · XLSX · HTML · CSV · ZIP</span></div><div class="dropzone" role="button" tabindex="0" aria-label="Загрузить оборотно-сальдовую ведомость"><div class="upload-icon">${I('upload')}</div><strong>Перетащите ОСВ сюда или <span>выберите файл</span></strong><p>Excel, HTML или CSV из 1С · можно загрузить ZIP-архив</p></div><div class="upload-note">${I('lock')}Файлы обрабатываются на устройстве и не отправляются на сервер.</div></section><section class="panel coverage-panel"><div class="panel-head"><div><h2>Покрытие отчётного года</h2><p>Какие месяцы можно рассчитать</p></div><span class="year-tag">${state.year}</span></div><div class="month-grid">${cov.map((m,i)=>`<div class="month-tile ${m.ready?'ready':m.covered?'covered':''}" title="${E.MONTH_NAMES[i]}: ${m.ready?'можно рассчитать':m.covered?'входит в общую ОСВ':'нет данных'}">${['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'][i]}</div>`).join('')}</div><div class="coverage-legend"><span><span class="legend-square"></span>Можно рассчитать месяц</span><span><span class="legend-square light"></span>Входит в общую ОСВ</span></div><p class="coverage-note">ОСВ за несколько месяцев не разбивается поровну. Для отдельного месяца нужны данные на его границах.</p></section></div>`;}
function defaultPeriod(f){return E.periodFor(f.frequency,state.year,f.frequency==='year'?1:f.frequency==='quarter'?Math.ceil(part/3):Math.min(part,12));}
const key=c=>c.sheet+'!'+c.cell;
function draft(f,p,create=false){const k=f.id+':'+p.key;if(create&&!C().drafts[k])C().drafts[k]={values:{},reviewed:false};return C().drafts[k]||{values:{},reviewed:false};}
function ctxFor(f,p){const y=+p.start.slice(0,4),m=+p.start.slice(5,7),prev=f.frequency==='month'?E.periodFor('month',m===1?y-1:y,m===1?12:m-1):E.periodFor('year',y-1);return{ss:sources(),current:E.resolve(sources(),p.start,p.end),previous:E.resolve(sources(),prev.start,prev.end),prev,mappingOK:C().mappingConfirmed&&!E.mappingChecks(C().rules,accounts()).length};}
function automatic(f,p,row,col,ctx){if(!ctx.mappingOK)return null;const get=(bucket,prev=false)=>{const rule=C().rules[bucket];if(!rule)return null;const r=prev?ctx.previous:ctx.current,v=E.turnover(r,rule.accounts,rule.method);return v==null?null:{value:E.round(v/1000,1),kind:'auto',source:`Оборот ${rule.method==='net'?'Кт − Дт':'Кт'} ${rule.accounts} / 1 000`,path:r.path};};const stock=(prev=false)=>{const r=E.stock(ctx.ss,prev?ctx.prev.end:p.end,C().rules.stock.accounts);return r.ok?{value:E.round(r.value/1000,1),kind:'auto',source:'Сальдо Дт − Кт '+C().rules.stock.accounts+' / 1 000',path:[{id:r.source,sign:1}]}:null;};
 if(f.id==='t1'&&['current','prev'].includes(col))return get(({'01':'wholesale','02':'retail','03':'hotel','04':'food','05':'realty','06':'services','07':'internet'})[row.code],col==='prev');
 if(f.id==='t14'&&row.code==='09'&&col==='market')return get('market');
 if(f.id==='t3'){if(['current','prev'].includes(col)){if(row.code==='01')return get('retail',col==='prev');if(row.code==='03')return get('internet',col==='prev');if(row.code==='05')return stock(col==='prev');}if(row.code==='06'&&col==='sales')return get('retail');if(row.code==='06'&&col==='stock')return stock();}return null;
}
function reportData(f,p){const ctx=ctxFor(f,p),d=draft(f,p),cells=[],checks=[];let missing=0,invalid=0;for(const sec of f.sections)for(const row of sec.rows)for(const[col,c]of Object.entries(row.cells)){const k=key(c),optional=!!c.optional||(c.quarterOnly&&!['03','06','09','12'].includes(p.start.slice(5,7))),meta={...c,optional};let v;if(Object.hasOwn(d.values,k)){const raw=d.values[k];v={value:raw===''?null:c.type==='text'?raw:E.number(raw),kind:'manual',source:'Введено вручную'};}else v=automatic(f,p,row,col,ctx)||{value:null,kind:'empty',source:'Нужны дополнительные данные'};let error='';if(v.value!=null&&c.type!=='text'){if(!Number.isFinite(v.value))error='Введите число';else if(v.value<0)error='Отрицательное значение';else if(c.type==='integer'&&!Number.isInteger(v.value))error='Нужно целое число';else if(c.type==='boolean'&&![0,1].includes(v.value))error='Только 0 или 1';else if(c.type==='percentage'&&v.value>100)error='Процент больше 100';else if(c.quarterOnly&&optional)error='Только в квартальном отчёте';}if(v.value==null&&!optional)missing++;if(error)invalid++;cells.push({key:k,sec:sec.id,row:row.code,col,meta,label:row.label,...v,error});}
 if(!C().name.trim()||C().name==='Моя организация')checks.push({text:'Заполните название организации',action:'company'});if(!C().okpo.trim())checks.push({text:'Заполните ОКПО организации',action:'company'});if(missing)checks.push({text:'Не заполнено показателей: '+missing+'. Пустое поле не равно нулю.'});if(invalid)checks.push({text:'Некорректные значения: '+invalid+'. Проверьте поля.'});
 const val=(r,c)=>cells.find(x=>x.row===r&&x.col===c)?.value;
 if(f.id==='t14')for(const col of ['market','center']){const a=val('01',col),b=val('02',col),parts=['03','04','05'].map(r=>val(r,col));if(a!=null&&b!=null&&b>a)checks.push({text:'Строка 02 больше строки 01 ('+(col==='market'?'рынок':'ТЦ')+')'});if(b!=null&&parts.every(v=>v!=null)&&Math.abs(parts.reduce((a,b)=>a+b,0)-b)>.01)checks.push({text:'Строки 03 + 04 + 05 должны равняться строке 02 ('+(col==='market'?'рынок':'ТЦ')+')'});if(val('10',col)>(Date.parse(p.end)-Date.parse(p.start))/86400000+1)checks.push({text:'Число дней больше длительности квартала'});}
 if(f.id==='t1')for(const r of ['02','03','04','05','06','07'])if(val(r,'population')!=null&&val(r,'prev')!=null&&val(r,'population')>val(r,'prev'))checks.push({text:'Строка '+r+': продажи населению больше общего объёма прошлого месяца'});
 if(f.id==='t3'){for(const col of ['prev','current'])for(const r of ['02','03','04'])if(val('01',col)!=null&&val(r,col)!=null&&val(r,col)>val('01',col))checks.push({text:'Строка '+r+' больше строки 01'});for(const[a,b,ca,cb]of [['01','06','current','sales'],['05','06','current','stock'],['02','07','current','sales']])if(val(a,ca)!=null&&val(b,cb)!=null&&Math.abs(val(a,ca)-val(b,cb))>.11)checks.push({text:'Строки '+a+' и '+b+' должны содержать согласованные суммы'});}
 if(f.id==='p1')for(const row of f.sections.find(s=>s.id==='products').rows){const cc=cells.filter(c=>c.sec==='products'&&c.row===row.code);if(cc.some(c=>c.value!=null)&&cc.some(c=>c.value==null))checks.push({text:'Продукция '+row.code+': заполните наименование, единицу, ГСКП и все периоды'});}
 return{cells,ctx,draft:d,checks,missing,invalid,total:cells.filter(c=>!c.meta.optional).length,filled:cells.filter(c=>!c.meta.optional&&c.value!=null&&!c.error).length,ready:checks.length===0&&d.reviewed};}
function tabs(){return`<div class="period-tabs">${[['all','Все'],['month','Месячные'],['quarter','Квартальные'],['year','Годовые']].map(([k,l])=>`<button class="period-tab ${frequency===k?'active':''}" data-action="frequency" data-value="${k}">${l}</button>`).join('')}</div>`;}
function cards(){return`<div class="form-grid">${F.filter(f=>frequency==='all'||frequency===f.frequency).map(f=>{const p=defaultPeriod(f),r=reportData(f,p),tag=r.ready?['Проверен','green']:r.filled?['Заполнено '+r.filled+' из '+r.total,'amber']:!sources().length?['Загрузите ОСВ','']:!['t1','t14','t3'].includes(f.id)?['Дополните вручную','amber']:!r.ctx.current.ok?['Нет ОСВ за этот период','amber']:!C().mappingConfirmed?['Выберите вид деятельности','amber']:['Нужны сведения','amber'];return`<article class="form-card"><div class="form-card-top"><span class="form-icon ${f.frequency==='quarter'?'blue':f.frequency==='year'?'gold':''}">${I('file')}</span><span class="frequency-tag">${freqNames[f.frequency]}</span></div><h3>${esc(f.title)}</h3><p class="form-description">${esc(f.description)}</p><div class="form-meta"><span>ГКУД ${f.gkud}</span><span class="badge ${tag[1]}">${tag[0]}</span></div><div class="form-card-bottom"><span class="card-footnote">${p.label}</span><button class="text-button" data-action="report" data-form="${f.id}">Открыть форму ${I('arrow')}</button></div></article>`;}).join('')}</div>`;}
function importTable(limit=0){let ss=sources().slice().reverse();if(limit)ss=ss.slice(0,limit);return`<div class="table-wrap"><table><thead><tr><th>Файл ведомости</th><th>Период</th><th>Счетов</th><th>Проверка</th><th></th></tr></thead><tbody>${ss.length?ss.map(s=>{const n=E.sourceChecks(s).length;return`<tr><td><div class="file-name">${I('file')}<div><strong>${esc(s.filename)}</strong><small>${esc(s.org)}</small></div></div></td><td class="small">${E.dateLabel(s.start)} — ${E.dateLabel(s.end)}<br><span class="muted">${s.unit==='thousand'?'тыс. сом':'сом'}</span></td><td class="mono">${Object.keys(s.accounts).length}</td><td><span class="badge ${n?'red':'green'}">${n?'Замечания: '+n:'ОСВ сходится'}</span></td><td><button class="icon-button" data-action="source-edit" data-id="${s.id}" aria-label="Период и единицы ОСВ">${I('edit')}</button><button class="icon-button" data-action="source-open" data-id="${s.id}" aria-label="Просмотреть счета">${I('arrow')}</button></td></tr>`;}).join(''):`<tr><td colspan="5" class="table-empty">${I('file')}Здесь появятся загруженные ведомости</td></tr>`}</tbody></table></div>`;}
function overview(){return heading('От ОСВ — к отчётности','Подготовьте месячные, квартальные и годовые отчёты по данным вашей бухгалтерии.',`<button class="btn" data-action="demo">${I('file')}Открыть пример</button>${uploadButton()}`)+toolbar()+sourceOverview()+stats()+intake()+`<div class="section-heading"><div><h2>Формы отчётности</h2><p>Официальные бланки, расчёты и дополнительные сведения</p></div>${tabs()}</div>`+cards()+`<section class="panel"><div class="panel-head"><h2>Последние ведомости</h2><button class="text-button" data-action="nav" data-page="sources">Все ведомости ${I('arrow')}</button></div>${importTable(3)}</section>`;}
function sourcesPage(){const ss=sources(),s=ss.find(s=>s.id===sourceId)||ss.at(-1);if(s)sourceId=s.id;return heading('Оборотно-сальдовые ведомости','Загружайте месячные и накопительные ОСВ. Ведомости разных организаций учитываются отдельно.',uploadButton())+toolbar()+`<section class="panel block-space"><div class="panel-head"><h2>Загруженные файлы</h2><button class="text-button" data-action="restore">Восстановить копию</button></div>${importTable()}</section>`+(s?`<section class="panel"><div class="panel-head"><div><h2>Распознанные счета</h2><p>Валютная аналитика не дублируется в итогах</p></div><select class="select" id="source-select" aria-label="Ведомость для просмотра">${ss.map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${esc(x.filename)}</option>`).join('')}</select></div><div class="detail-bar"><span>${esc(s.title)}</span><span>${s.ignored} служебных и аналитических строк исключено</span></div><div class="table-wrap"><table class="account-table"><thead><tr><th>Счёт</th><th>Наименование</th><th>Начало Дт</th><th>Начало Кт</th><th>Оборот Дт</th><th>Оборот Кт</th><th>Конец Дт</th><th>Конец Кт</th></tr></thead><tbody>${Object.entries(s.accounts).sort(([a],[b])=>a.localeCompare(b)).map(([c,a])=>`<tr><td class="mono">${c}</td><td>${esc(a.label||'Счёт '+c)}</td>${E.KEYS.map(k=>`<td>${fmt(a[k])}</td>`).join('')}</tr>`).join('')}<tr style="background:#f4f9f5;font-weight:600"><td colspan="2">Итого без повторов субсчетов</td>${E.KEYS.map(k=>`<td>${fmt(E.totals(s.accounts)[k])}</td>`).join('')}</tr></tbody></table></div></section>`:intake());}
function reportsPage(){return heading('Статистические отчёты','Выберите форму и период. Дополните показатели, которых нет в общей ОСВ.',`<button class="btn primary" data-action="bulk">${I('package')}Сформировать пакет</button>`)+toolbar()+sourceOverview()+`<div class="notice block-space">${I('info')}<div>Неполные формы выгружаются с отметкой «Черновик». Отправка выполняется отдельно через кабинет респондента. Совместимость файла с импортом в АИС IST не подтверждена.</div></div><div class="section-heading">${tabs()}<label class="small muted">Период <select class="select" id="report-part">${E.MONTH_NAMES.map((n,i)=>`<option value="${i+1}" ${part===i+1?'selected':''}>${n} / ${Math.ceil((i+1)/3)} кв.</option>`).join('')}</select></label></div>`+cards();}
function mappingPage(){
 const src=selectedSource(),data=src?E.sourceSummary(src):null;
 return heading('Сопоставление счетов','Выберите вид деятельности или укажите счета вручную. Нажмите «Применить и пересчитать», чтобы сохранить настройки.',`<button class="btn" data-action="quick-setup">Простая настройка</button><button class="btn primary" data-action="mapping-confirm">${I('check')}Применить и пересчитать</button>`)+toolbar()+setupBanner()+
 (data?.closedIncome?`<div class="notice amber block-space"><div><strong>По счёту 6110 Кт = Дт = ${fmt(data.credit6110)} сом.</strong><br>Разность «Кт − Дт» даёт ноль. Дебет может включать закрытие доходов. Для исходной суммы реализации проверьте кредитовый оборот.</div></div>`:'')+
 `<div class="notice block-space"><div id="mapping-feedback">${C().mappingConfirmed?'Настройки применены.':'Настройки ещё не применены.'} Изменение выпадающего списка само по себе не подтверждает настройку и не создаёт отсутствующие периоды.</div></div><section class="panel table-wrap"><table class="mapping-table"><thead><tr><th>Показатель</th><th>Счета</th><th>Источник суммы</th><th>Применение</th></tr></thead><tbody>${Object.entries(mapNames).map(([k,l])=>`<tr><td>${l}</td><td><input class="input mapping-input" data-map="${k}" data-field="accounts" value="${esc(C().rules[k]?.accounts||'')}" placeholder="Номер счёта или субсчёта" aria-label="Счета: ${l}"></td><td>${k==='stock'?'<span class="small muted">Конечное сальдо Дт − Кт</span>':`<select class="select mapping-input" data-map="${k}" data-field="method" aria-label="Расчёт: ${l}"><option value="credit">Оборот Кт</option><option value="net" ${C().rules[k]?.method==='net'?'selected':''}>Оборот Кт − Дт</option></select>`}</td><td class="small muted">${k==='stock'?'3-торг: 05':k==='market'?'14-торг: 09':k==='internet'?'1-торг: 07, 3-торг: 03':'1-торг'+(k==='retail'?', 3-торг':'')}</td></tr>`).join('')}</tbody></table></section><div class="storage-note">6120 — возвраты и скидки; он не прибавляется к выручке. 1650 — сельхозпродукция, а не универсальный счёт запасов. НДС, возвраты и состав показателей проверяются отдельно. Для смешанной деятельности используйте аналитику или ручную разбивку.</div>`;
}
function checksPage(){const ss=sources(),list=issues();return heading('Проверка данных','Контроль остатков, оборотов, периодов и назначения счетов.',uploadButton())+toolbar()+`<div class="check-list">${!ss.length?`<div class="check-item"><span class="check-icon">${I('file')}</span><div><strong>Добавьте первую ведомость</strong><p>После загрузки появятся результаты проверок.</p></div></div>`:''}${list.map(i=>`<div class="check-item ${i.level==='error'?'error':''}"><span class="check-icon">${I('warning')}</span><div><strong>${esc(i.text)}</strong>${i.source?`<p>${esc(ss.find(s=>s.id===i.source)?.filename)}</p>`:''}</div>${i.action?`<button class="btn sm" data-action="${i.action==='company'?'company':'nav'}" data-page="mapping">Исправить</button>`:i.source?`<button class="icon-button" data-action="source-edit" data-id="${i.source}" aria-label="Проверить ведомость">${I('edit')}</button>`:''}</div>`).join('')}${ss.filter(s=>!E.sourceChecks(s).length).map(s=>`<div class="check-item success"><span class="check-icon">${I('check')}</span><div><strong>Остатки и обороты сходятся</strong><p>${esc(s.filename)} · ${Object.keys(s.accounts).length} счетов · ${E.dateLabel(s.start)} — ${E.dateLabel(s.end)}</p></div></div>`).join('')}</div><div class="notice" style="margin-top:22px">${I('info')}<div>Равенство подтверждает арифметику ОСВ. Полнота и предусмотренные соотношения статистических показателей проверяются в каждой форме отдельно.</div></div>`;}
function render(){if(!['overview','calculation','sources','reports','mapping','checks'].includes(page))page='overview';const nav=[['overview','dashboard','Обзор'],['calculation','reports','Расчёт из ОСВ'],['sources','file','Ведомости'],['reports','reports','Отчёты'],['checks','check','Проверка данных'],['mapping','mapping','Сопоставление счетов']];document.getElementById('navigation').innerHTML=nav.map(([k,i,l])=>`<button class="nav-item ${page===k?'active':''}" data-action="nav" data-page="${k}">${I(i)}${l}${k==='sources'||k==='reports'?`<span class="nav-badge">${k==='sources'?sources().length:6}</span>`:''}</button>`).join('');document.getElementById('breadcrumb-current').textContent=nav.find(x=>x[0]===page)[2];document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=I(n.dataset.icon));document.getElementById('main').innerHTML=({overview,calculation:calculationPage,sources:sourcesPage,reports:reportsPage,mapping:mappingPage,checks:checksPage})[page]();if(C().isDemo)document.getElementById('main').insertAdjacentHTML('afterbegin','<div class="notice amber block-space">Демонстрационная организация. Все суммы и ведомости вымышлены.</div>');if(storageError)document.getElementById('main').insertAdjacentHTML('afterbegin','<div class="notice amber block-space">Сохранение в браузере недоступно. Скачайте JSON-копию перед закрытием.</div>');bindDrops();}
function nav(p){page=p;location.hash=p;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0);}
function modal(title,sub,body,foot='',wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${I('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal-close').focus();}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';ms=null;render();}
function companyModal(isNew=false){ms={type:'company',isNew};const c=isNew?newCompany(''):C();modal('Организация','Реквизиты для титульных листов отчётов.',`<form id="company-form"><div class="fields-grid">${[['name','Наименование организации'],['okpo','ОКПО · 8 цифр'],['inn','ИНН · 14 цифр'],['gked','ГКЭД'],['territory','Территория'],['address','Адрес'],['activity','Вид экономической деятельности'],['director','Руководитель'],['phone','Телефон'],['email','Электронная почта']].map(([k,l])=>`<div class="field ${['name','activity'].includes(k)?'full':''}"><label class="label" for="company-${k}">${l}</label><input class="input" id="company-${k}" name="${k}" value="${esc(c[k])}" ${k==='name'?'required':''} ${k==='email'?'type="email"':''}></div>`).join('')}</div></form><div class="storage-note">Каждая организация хранит отдельные ведомости, назначения счетов и ручные значения.</div>`,`<button class="text-button" data-action="company-new">${I('plus')}Добавить организацию</button><button class="btn primary" data-action="company-save">Сохранить</button>`);}
function openReport(formId,p=null,section=null){const f=F.find(x=>x.id===formId);p??=defaultPeriod(f);ms={type:'report',formId,period:p,section:section||f.sections[0].id};const r=reportData(f,p);modal(esc(f.title),esc(f.description)+' · ГКУД '+f.gkud,`<div class="print-heading"><strong>${esc(f.title)} · ${p.label} · ${r.ready?'Проверен':'ЧЕРНОВИК'}</strong><p>${esc(C().name)} · ОКПО ${esc(C().okpo)}</p></div><div class="editor-toolbar"><div class="actions"><label class="small muted">Период</label><select class="select" id="editor-period" aria-label="Период отчёта">${Array.from({length:f.frequency==='month'?12:f.frequency==='quarter'?4:1},(_,i)=>{const pp=E.periodFor(f.frequency,state.year,i+1);return`<option value="${i+1}" ${p.key===pp.key?'selected':''}>${pp.label}</option>`;}).join('')}</select><span id="report-status"></span></div><div class="actions"><button class="btn sm" data-action="template" data-form="${f.id}">${I('download')}Бланк</button><button class="btn sm" data-action="print">${I('print')}Печать / PDF</button></div></div><div class="notice">${I('info')}<div>${['p1','ec','t12'].includes(f.id)?'Для этой формы нужны сведения первичного, кадрового или товарного учёта. Внесите их вручную.':'Зелёные ячейки рассчитаны по подтверждённым счетам. Любое значение можно исправить вручную. Пустая ячейка означает отсутствие данных.'}</div></div><div id="report-source"></div><div class="section-tabs">${f.sections.map(s=>`<button class="section-tab ${s.id===ms.section?'active':''}" data-action="section" data-section="${s.id}">${esc(s.title)}</button>`).join('')}</div>${f.sections.map(s=>`<section class="editor-section" data-section="${s.id}" ${s.id!==ms.section?'style="display:none"':''}><div class="print-heading">${esc(s.title)}</div><div class="panel table-wrap"><table class="editor-table"><thead><tr><th>Строка</th><th>Показатель</th>${s.columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${s.rows.map(row=>`<tr><td class="code mono">${row.code}</td><td>${esc(row.label)}${row.unit?`<small>${esc(row.unit)}</small>`:''}</td>${s.columns.map(col=>{const c=row.cells[col.key];if(!c)return'<td style="text-align:center;color:#c4d0c6">×</td>';const v=r.cells.find(x=>x.key===key(c));return`<td><input class="cell-input ${v.kind==='auto'?'auto':v.kind==='manual'?'manual':''}" data-cell="${esc(v.key)}" type="text" inputmode="${c.type==='text'?'text':'decimal'}" value="${esc(v.value==null?'':Number.isNaN(v.value)?r.draft.values[v.key]:v.value)}" placeholder="—" aria-label="${esc(row.code+' '+row.label+' '+col.label)}" title="${esc(v.error||v.source)}"><div class="cell-origin">${esc(v.error||(v.kind==='auto'?'из ОСВ':v.kind==='manual'?'вручную':'нужны сведения'))}</div></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`).join('')}<div class="editor-checks" id="report-checks"></div><div class="editor-actions actions" style="justify-content:space-between;margin-top:17px"><button class="text-button" data-action="fill-zero">Пустые поля раздела = 0</button><button class="text-button" data-action="reset-values">Сбросить ручные значения раздела</button></div><div class="storage-note">Бланк: <a href="${f.source}" target="_blank" rel="noopener">Нацстатком КР ↗</a> · Проверено ${f.checked}.<br>Файл предназначен для проверки и переноса данных. Совместимость с импортом в АИС IST не подтверждена.${f.id==='p1'?'<br>Исходный XLS преобразуется в XLSX; оформление может отличаться.':''}</div>`,`<div class="editor-progress" id="report-progress"></div><div class="actions" id="report-footer"></div>`,true);refreshReport();}
function selectedSource(period=null){
 const ss=sources();
 if(period){const exact=ss.find(s=>s.start===period.start&&s.end===period.end);if(exact)return exact;}
 const chosen=ss.find(s=>s.id===sourceId);if(chosen)return chosen;
 const sorted=ss.slice().sort((a,b)=>String(b.end||'').localeCompare(String(a.end||'')));
 return period?sorted.find(s=>s.end>=period.start&&s.end<=period.end)||sorted[0]:sorted[0];
}
function setupBanner(){
 if(!sources().length)return '';
 const fixed=C().mappingRepairNotice;
 const title=C().mappingConfirmed?'Назначение счетов применено':'Один шаг для распределения выручки';
 const description=fixed?'Исправлены ошибочные исходные значения 6120 и 1650. Выберите фактический вид деятельности. Ваши ОСВ и ручные значения сохранены.':C().mappingConfirmed?'Результаты зависят от покрытия периода. Если ОСВ общая за несколько месяцев, отдельный месяц не восстанавливается автоматически.':'Сначала приложение показывает суммы из файла. Затем выберите, к какому виду деятельности относится выручка. Переключать все строки Дт/Кт не требуется.';
 return `<div class="setup-banner"><div><strong>${title}</strong><p>${description}</p></div><div class="actions"><button class="btn ${C().mappingConfirmed?'':'primary'} sm" data-action="quick-setup">${C().mappingConfirmed?'Изменить вид деятельности':'Выбрать вид деятельности'}</button><button class="btn sm" data-action="nav" data-page="calculation">Расчёт из ОСВ</button></div></div>`;
}
function sourceOverview(){const s=selectedSource();return s?V.sourcePanel(s,sources())+setupBanner():'';}
function calculationPage(){
 const src=selectedSource();
 const head=heading('Автоматический расчёт из ОСВ','Суммы видны сразу после загрузки. Они относятся к точному периоду выбранного файла.',uploadButton())+toolbar();
 if(!src)return head+intake();
 const available=[['month','Месячные обороты',12],['quarter','Квартальные обороты',4],['year','Годовые обороты',1]].map(([frequency,label,count])=>{const periods=Array.from({length:count},(_,i)=>E.periodFor(frequency,state.year,i+1)),ready=periods.filter(p=>E.resolve(sources(),p.start,p.end).ok);return {label,count,ready};});
 return head+V.sourcePanel(src,sources())+setupBanner()+`<section class="panel block-space"><div class="panel-head"><div><h2>Какие периоды ${state.year} года покрыты данными</h2><p>Наличие периода позволяет рассчитать обороты. Остальные показатели формы могут требовать дополнения.</p></div><button class="btn sm" data-action="nav" data-page="reports">Перейти к статформам</button></div><div class="table-wrap"><table><thead><tr><th>Расчёт</th><th>Доступно</th><th>Периоды</th></tr></thead><tbody>${available.map(a=>`<tr><td>${a.label}</td><td>${a.ready.length} из ${a.count}</td><td>${a.ready.length?a.ready.map(p=>p.label).join(', '):'Нужны ОСВ на границы соответствующих периодов'}</td></tr>`).join('')}</tbody></table></div></section><div class="notice">Общая ведомость за январь–август даёт общий оборот за восемь месяцев. Для августа нужна ОСВ за август либо разность январь–август и январь–июль одной организации.</div>`;
}
function quickSetup(){
 const back=ms?.type==='report'?{formId:ms.formId,period:ms.period,section:ms.section}:null;
 const s=selectedSource(),selected=C().quickActivity||'',income=selected&&C().rules[selected]?.accounts?C().rules[selected].accounts:E.selectedCodes(accounts(),'6110').length?'6110':'';
 ms={type:'quick',back};
 modal('Куда относится выручка?','Один вид деятельности для выбранных счетов.',`<form id="quick-form"><div class="fields-grid"><div class="field full"><label class="label" for="quick-activity">Фактический вид деятельности</label><select class="input" id="quick-activity" name="activity" required><option value="">Выберите вид деятельности</option>${['wholesale','retail','hotel','food','realty','services','market'].map(k=>`<option value="${k}" ${selected===k?'selected':''}>${mapNames[k]}</option>`).join('')}</select></div><div class="field"><label class="label" for="quick-income">Счёт выручки</label><input class="input" id="quick-income" name="income" value="${esc(income)}" placeholder="Например, 6110" required></div><div class="field"><label class="label">Способ расчёта</label><div class="input">Кредитовый оборот за нужный период</div></div><div class="field full"><label class="checkbox-label"><input type="checkbox" name="retailStock" ${selected==='retail'&&C().rules.stock.accounts==='1610'?'checked':''}>На счёте 1610 учитываются товары для продажи населению — использовать его для строки запасов 3-торг.</label></div></div></form>${s?`<div class="notice" style="margin-top:18px"><div>В выбранной ОСВ оборот Кт 6110: <strong>${fmt(E.sourceSummary(s).credit6110)} сом</strong> за ${E.dateLabel(s.start)} — ${E.dateLabel(s.end)}. Эти суммы не распределяются поровну между месяцами.</div></div>`:''}<div class="storage-note">Нажатие «Применить» относит всю выручку указанных счетов к одному выбранному виду деятельности и заменяет прежние назначения этой организации. При смешанной деятельности используйте подробную настройку по субсчетам. НДС, возвраты и агентские операции проверяются отдельно.</div>`,`<button class="text-button" data-action="advanced-mapping">Подробная настройка</button><button class="btn primary" data-action="quick-apply">Применить и пересчитать</button>`);
}
function applyQuickSetup(){
 const form=document.getElementById('quick-form');if(!form.reportValidity())return;
 const fields=new FormData(form),activity=fields.get('activity'),income=String(fields.get('income')).trim(),stock=fields.has('retailStock')?'1610':'';
 if(!E.selectedCodes(accounts(),income).length){toast('Указанные счета не найдены в ведомостях этой организации.',true);return;}
 const rules=E.quickRules(activity,income,stock),errors=E.mappingChecks(rules,accounts());if(errors.length){toast(errors[0].text,true);return;}
 const back=ms.back;C().rules=rules;C().quickActivity=activity;C().mappingConfirmed=true;C().mappingRepairNotice=false;C().mappingRevision=2;
 invalidate();save();
 if(back)openReport(back.formId,back.period,back.section);else{closeModal();nav('reports');}
 toast('Вид деятельности применён. Показатели покрытых периодов пересчитаны.');
}
function exportSourceSummary(id){
 const s=sources().find(s=>s.id===id);if(!s)throw Error('Ведомость не найдена');
 const v=E.sourceSummary(s),rows=[['РАСЧЁТ ПО ПЕРИОДУ ОСВ — ПРЕДВАРИТЕЛЬНЫЕ ДАННЫЕ'],['Организация',C().name],['Исходный файл',s.filename],['Начало периода',s.start],['Конец периода',s.end],['Единицы','сом'],[],['Показатель','Сумма, сом','Источник'],['Кредитовый оборот 6110',v.credit6110,'Оборот Кт за полный период ОСВ'],['Дебетовый оборот 6110',v.debit6110,'Оборот Дт за полный период ОСВ'],['Разность Кт − Дт 6110',v.net6110,'Может быть нулём после закрытия доходов'],['Остаток счёта 1610',v.stock1610,'Конечное сальдо Дт − Кт'],['Дебетовый оборот 6120',v.debit6120,'Возвраты и скидки, показаны отдельно'],[],['Назначение','Это расчёт за период исходного файла, а не месячный, квартальный или годовой отчёт за другой период.'],['Статус проверки',v.issues.length?v.issues.map(i=>i.text).join('; '):'Арифметика ОСВ сходится'],['Отсутствующий счёт','Пустая сумма означает, что счёт в файле не найден.'],['Дальнейшие действия','Выберите вид деятельности; для статформы проверьте период, НДС, возвраты и недостающие натуральные показатели.']];
 const wb=XLSX.utils.book_new(),sheet=XLSX.utils.aoa_to_sheet(rows);sheet['!cols']=[{wch:40},{wch:28},{wch:65}];
 for(let r=9;r<=13;r++)if(sheet['B'+r]?.t==='n')sheet['B'+r].z='#,##0.00';
 XLSX.utils.book_append_sheet(wb,sheet,'Расчёт ОСВ');
 const raw=[['Исходные суммы в файле',s.unit==='thousand'?'тыс. сом':'сом'],['Период',s.start+' — '+s.end],[],['Счёт','Начало Дт','Начало Кт','Оборот Дт','Оборот Кт','Конец Дт','Конец Кт'],...Object.keys(s.accounts).sort().map(code=>[code,...E.KEYS.map(k=>s.accounts[code][k])])];
 const rawSheet=XLSX.utils.aoa_to_sheet(raw);rawSheet['!cols']=Array.from({length:7},()=>({wch:20}));XLSX.utils.book_append_sheet(wb,rawSheet,'Счета исходной ОСВ');
 download(XLSX.write(wb,{type:'array',bookType:'xlsx'}),'Расчёт_ОСВ_'+(s.start||'период')+'_'+(s.end||'не-указан')+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
 toast('Расчёт за период файла скачан. Он не заменяет статформу за другой период.');
}
function refreshReport(){
 if(ms?.type!=='report')return;
 const f=F.find(f=>f.id===ms.formId),r=reportData(f,ms.period);
 document.getElementById('report-status').innerHTML=`<span class="badge ${r.ready?'green':'amber'}">${r.ready?'Проверен':'Черновик'}</span>`;
 document.getElementById('report-progress').innerHTML=`<div class="progress-track"><span style="width:${r.total?r.filled/r.total*100:0}%"></span></div>${r.filled} / ${r.total} показателей`;
 document.getElementById('report-source').innerHTML=V.reportGuidance(f,ms.period,r,C(),sources(),selectedSource(ms.period));
 document.getElementById('report-checks').innerHTML=r.checks.slice(0,7).map(c=>`<div class="editor-check-line">${I('warning')}<span>${esc(c.text)}</span>${c.action?`<button class="text-button" data-action="company">Исправить</button>`:''}</div>`).join('')+(!r.checks.length?`<div class="editor-check-line success">${I('check')}Обязательные поля и предусмотренные контрольные соотношения заполнены.</div><label class="checkbox-label"><input id="review-check" type="checkbox" ${r.draft.reviewed?'checked':''}>Я проверил показатели, единицы и применимость формы по указаниям Нацстаткома.</label>`:'');
 document.getElementById('report-footer').innerHTML=`<button class="btn" data-action="export-report" data-draft="1">${I('download')}Скачать черновик</button><button class="btn primary" data-action="export-report" ${r.ready?'':'disabled'}>${I('download')}Скачать отчёт</button>`;
}
function sourceModal(id){const s=state.sources.find(s=>s.id===id);if(!s)return;ms={type:'source',id};modal('Период и единицы ОСВ',esc(s.filename),`<div class="notice block-space">${I('info')}<div>${esc(s.title)}. Укажите фактические границы выгрузки. Изменение дат не пересчитывает обороты файла.</div></div><form id="source-form"><div class="fields-grid"><div><label class="label">Начало периода</label><input class="input" name="start" type="date" value="${s.start}" required></div><div><label class="label">Конец периода</label><input class="input" name="end" type="date" value="${s.end}" required></div><div><label class="label">Единицы исходного файла</label><select class="input" name="unit"><option value="som">Сомы</option><option value="thousand" ${s.unit==='thousand'?'selected':''}>Тысячи сомов</option></select></div><div><label class="label">Организация</label><select class="input" name="companyId">${state.companies.map(c=>`<option value="${c.id}" ${s.companyId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div></form><div class="check-list" style="margin-top:20px">${E.sourceChecks(s).map(i=>`<div class="notice red">${I('warning')}<span>${esc(i.text)}</span></div>`).join('')||`<div class="notice">${I('check')}Остатки и обороты сходятся.</div>`}</div>`,`<button class="text-button" data-action="delete-source" data-id="${s.id}">Убрать ведомость</button><button class="btn primary" data-action="save-source">Сохранить</button>`);}
